const check = (text, options, answer, explanation) => [text, options, answer, explanation];
const lesson = (title, objectives, explanation, example, steps, activity, checks) => ({
  title, duration: '45–75 minutes', objectives,
  sections: [['Understand the idea', explanation], ['Work through an example', example], ['Practise and review', activity]],
  steps, activity, evidence: 'Keep your work, a test or observation record, and a short explanation of one improvement.', checks,
});

